# helper to parse gmail created_at

def parse_gmail_dt(s):
    # expected like '2023-05-18T11:00:00'
    return datetime.fromisoformat(s.replace('Z',''))

def format_gmail_scheduled_dt(dt):
    return dt.strftime('%Y-%m-%d|%H:%M:%S')

outgoing_items = []  # list of dicts with thread_id, email_id, recipients, sent_at, scheduled_send_at

for t in threads:
