    if tid == thread0_id:
        detailed = thread0
    else:
        detailed = apis.gmail.show_thread(email_thread_id=tid, access_token=gmail_token)
    # collect outgoing emails sent by Kyle
    for e in detailed['emails']:
        sender = e['sender']['email']
        if sender == kyle_email:
            recipients = [r['email'] for r in e.get('recipients', [])]
